package com.jianbox.app;

import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.Gravity;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.ScrollView;
import android.widget.TextView;
import java.io.File;

/** Compact manager for the app-owned persistent download queue. */
public class DownloadActivity extends Activity {
    private JianData data; private LinearLayout rows; private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable refreshTask=new Runnable(){public void run(){render();handler.postDelayed(this,650);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);data=new JianData(this);Ui.applyTheme(data);if(UpdateGuard.enforce(this))return;build();}
    @Override protected void onResume(){super.onResume();if(!UpdateGuard.resume(this))return;handler.removeCallbacks(refreshTask);handler.post(refreshTask);}
    @Override protected void onPause(){handler.removeCallbacks(refreshTask);super.onPause();}
    private void build(){LinearLayout shell=Ui.vertical(this);shell.setBackground(Ui.GLASS?ImageStore.background(this,data.appBackgroundPath(),0x44000000,0,0x33FFFFFF,100,0,data.appBackgroundPosition()):Ui.bg(Ui.GREEN_PALE,0,this));LinearLayout head=Ui.horizontal(this);head.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,8));TextView back=Ui.text(this,"‹",28,Ui.TEXT,false);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());head.addView(back,Ui.lp(Ui.dp(this,38),Ui.dp(this,42)));LinearLayout title=Ui.vertical(this);title.addView(Ui.text(this,"下载管理",18,Ui.TEXT,true));title.addView(Ui.text(this,"应用内下载 · 支持断点续传与重试",10,Ui.MUTED,false));head.addView(title,Ui.weight(1));Button clear=Ui.button(this,"清理已完成",false);clear.setOnClickListener(v->clearCompleted());head.addView(clear,Ui.lp(Ui.dp(this,96),Ui.dp(this,38)));shell.addView(head);ScrollView scroll=new ScrollView(this);rows=Ui.vertical(this);rows.setPadding(Ui.dp(this,12),0,Ui.dp(this,12),0);scroll.addView(rows,new ScrollView.LayoutParams(-1,-2));shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=Ui.horizontal(this);bottom.setPadding(Ui.dp(this,12),Ui.dp(this,8),Ui.dp(this,12),Ui.dp(this,10));TextView location=Ui.text(this,"保存位置\n"+BrowserDownloads.destinationHint(this),9,Ui.TEXT,true);location.setGravity(Gravity.CENTER_VERTICAL);location.setBackground(Ui.bordered(Ui.SURFACE,Ui.BORDER,11,this));location.setPadding(Ui.dp(this,12),0,Ui.dp(this,8),0);location.setOnClickListener(v->chooseLocation(location));bottom.addView(location,new LinearLayout.LayoutParams(0,Ui.dp(this,56),1));shell.addView(bottom);setContentView(shell);}
    private void render(){if(rows==null)return;rows.removeAllViews();java.util.List<DownloadStore.Record> list=DownloadStore.all(this);for(DownloadStore.Record r:list)addRow(r);if(list.isEmpty()){TextView empty=Ui.text(this,"还没有下载任务\n网页下载会在这里显示",12,Ui.MUTED,false);empty.setGravity(Gravity.CENTER);rows.addView(empty,new LinearLayout.LayoutParams(-1,Ui.dp(this,180)));}}
    private void addRow(DownloadStore.Record r){LinearLayout card=Ui.card(this);LinearLayout line=Ui.horizontal(this);TextView name=Ui.text(this,r.name.isEmpty()?"下载文件":r.name,12,Ui.TEXT,true);name.setSingleLine(true);line.addView(name,Ui.weight(1));TextView state=Ui.text(this,statusLabel(r.status),10,r.status==DownloadStore.FAILED?Ui.RED:Ui.GREEN,true);line.addView(state);card.addView(line);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(r.total>0?(int)Math.min(100,r.done*100/r.total):(r.status==DownloadStore.COMPLETE?100:0));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.GREEN));card.addView(bar,new LinearLayout.LayoutParams(-1,Ui.dp(this,5)));String detail=r.status==DownloadStore.FAILED?r.error:r.total>0?formatBytes(r.done)+" / "+formatBytes(r.total):"正在获取文件大小";if(r.speed>0)detail+=" · "+formatBytes(r.speed)+"/秒";TextView info=Ui.text(this,detail,9,Ui.MUTED,false);info.setPadding(0,Ui.dp(this,5),0,Ui.dp(this,3));card.addView(info);TextView path=Ui.text(this,"保存："+(r.path.isEmpty()?BrowserDownloads.destinationHint(this):r.path),8,Ui.MUTED,false);path.setSingleLine(true);card.addView(path);LinearLayout actions=Ui.horizontal(this);Button open=Ui.button(this,"简盒打开",false),retry=Ui.button(this,BlobDownloads.isBlob(r.url)?"返回网页重试":r.status==DownloadStore.RUNNING?"下载中":"重新下载",false),remove=Ui.button(this,"删除",false);open.setEnabled(r.status==DownloadStore.COMPLETE&&new File(r.path).exists());open.setOnClickListener(v->startActivity(new Intent(this,InternalFileViewerActivity.class).putExtra(InternalFileViewerActivity.EXTRA_PATH,r.path).putExtra(InternalFileViewerActivity.EXTRA_MIME,r.mime).putExtra(InternalFileViewerActivity.EXTRA_NAME,r.name)));retry.setVisibility(r.status==DownloadStore.FAILED?android.view.View.VISIBLE:android.view.View.GONE);retry.setOnClickListener(v->{if(BlobDownloads.isBlob(r.url)){if(BrowserUrlRules.isWebUrl(r.pageUrl))BrowserActivity.open(this,r.pageUrl);android.widget.Toast.makeText(this,"请在原网页重新点击下载按钮",android.widget.Toast.LENGTH_LONG).show();return;}r.status=DownloadStore.QUEUED;r.error="";DownloadStore.put(this,r);Intent i=new Intent(this,BrowserDownloadService.class).putExtra(BrowserDownloadService.EXTRA_ID,r.id);if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);});remove.setOnClickListener(v->new android.app.AlertDialog.Builder(this).setTitle("删除下载文件？").setMessage("将删除任务记录和简盒目录内的文件。此操作不能撤销。").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{DownloadStore.remove(this,r.id,true);render();}).show());actions.addView(open,new LinearLayout.LayoutParams(0,Ui.dp(this,36),1));Ui.margin(open,0,0,6,0,this);if(retry.getVisibility()==android.view.View.VISIBLE){actions.addView(retry,new LinearLayout.LayoutParams(0,Ui.dp(this,36),1));Ui.margin(retry,0,0,6,0,this);}actions.addView(remove,new LinearLayout.LayoutParams(0,Ui.dp(this,36),1));card.addView(actions);rows.addView(card,new LinearLayout.LayoutParams(-1,-2));Ui.margin(card,0,0,0,8,this);}
    private void chooseLocation(TextView label){String[] options={"应用下载目录","内部私密目录"};LinearLayout info=Ui.vertical(this);info.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),Ui.dp(this,4));info.addView(Ui.text(this,"两种位置都由简盒管理，不再调用系统下载器。应用下载目录便于备份；内部目录更私密。已下载文件不会自动迁移。",10,Ui.MUTED,false));new android.app.AlertDialog.Builder(this).setTitle("选择保存位置").setView(info).setSingleChoiceItems(options,"内部私密目录".equals(data.downloadLocation())?1:0,(d,w)->{data.downloadLocation(options[w]);label.setText("保存位置\n"+BrowserDownloads.destinationHint(this));d.dismiss();}).setNegativeButton("取消",null).show();}
    private void clearCompleted(){new android.app.AlertDialog.Builder(this).setTitle("清理已完成任务？").setMessage("将删除已完成、失败任务及对应文件，正在下载的任务不受影响。").setNegativeButton("取消",null).setPositiveButton("确认清理",(d,w)->{DownloadStore.clearTerminal(this);render();}).show();}
    private String statusLabel(int s){if(s==DownloadStore.RUNNING)return"下载中";if(s==DownloadStore.QUEUED)return"排队中";if(s==DownloadStore.COMPLETE)return"已完成";if(s==DownloadStore.PAUSED)return"已暂停";if(s==DownloadStore.CANCELED)return"已取消";return"失败";}
    private String formatBytes(long v){if(v<1024)return v+" B";if(v<1024*1024)return String.format(java.util.Locale.ROOT,"%.1f KB",v/1024f);if(v<1024L*1024*1024)return String.format(java.util.Locale.ROOT,"%.1f MB",v/1024f/1024f);return String.format(java.util.Locale.ROOT,"%.2f GB",v/1024f/1024f/1024f);}
}
